<?php
declare(strict_types=1);
$cfgPath=dirname(__DIR__).'/backend/config/database.local.php';
if(!is_file($cfgPath)){http_response_code(503);exit('Website belum dikonfigurasi.');}
$cfg=require $cfgPath;
try{$pdo=new PDO(sprintf('mysql:host=%s;dbname=%s;charset=%s',$cfg['host'],$cfg['database'],$cfg['charset']??'utf8mb4'),$cfg['username'],$cfg['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}
catch(Throwable $e){error_log('[STIT WEBSITE] '.$e->getMessage());http_response_code(503);exit('Layanan sementara tidak tersedia.');}
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$campus=$pdo->query('SELECT * FROM campus_profile WHERE id=1')->fetch()?:[];
$news=$pdo->query('SELECT id,title,excerpt,body,category,image_url,published_at FROM news_posts WHERE published_at IS NOT NULL AND published_at<=UTC_TIMESTAMP() ORDER BY published_at DESC LIMIT 8')->fetchAll();
$programs=$pdo->query('SELECT code,name,degree_level FROM study_programs WHERE is_active=1 ORDER BY name')->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?=h($campus['tagline']??'Portal Informasi STIT Darul Ilmi Tasikmalaya')?>"><title>STIT Darul Ilmi Tasikmalaya</title><style>
:root{--navy:#102b46;--teal:#0d6870;--ink:#1d2939;--muted:#667085;--bg:#f5f8fb}*{box-sizing:border-box}body{margin:0;font:16px/1.65 system-ui,sans-serif;color:var(--ink);background:var(--bg)}a{color:inherit}.wrap{width:min(1120px,92%);margin:auto}.header{background:#fff;border-bottom:1px solid #e5eaf0}.nav{display:flex;justify-content:space-between;align-items:center;padding:16px 0;gap:18px}.brand{font-weight:850;color:var(--navy);font-size:19px}.brand small{display:block;color:var(--muted);font-size:12px;font-weight:500}.links{display:flex;gap:18px;flex-wrap:wrap}.links a{text-decoration:none;font-weight:650;font-size:14px}.hero{background:linear-gradient(125deg,#102b46,#0d6870);color:#fff;padding:76px 0}.hero h1{font-size:clamp(34px,5vw,54px);line-height:1.12;max-width:780px;margin:0 0 18px}.hero p{max-width:720px;color:#e0f1f1;font-size:18px}.btn{display:inline-block;background:#fff;color:#0d6870;padding:11px 18px;border-radius:8px;text-decoration:none;font-weight:750;margin-top:12px}.section{padding:42px 0}.section h2{font-size:27px;color:var(--navy);margin:0 0 8px}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px;margin-top:22px}.card{background:#fff;border:1px solid #e6ebf1;border-radius:14px;overflow:hidden}.card img{width:100%;height:165px;object-fit:cover}.cardbody{padding:18px}.tag{font-size:12px;color:var(--teal);font-weight:750}.card h3{margin:8px 0;font-size:19px;line-height:1.3}.info{background:#fff;border:1px solid #e6ebf1;border-radius:14px;padding:22px}.footer{background:var(--navy);color:#dce8f1;padding:30px 0;margin-top:30px}.footer a{color:#fff}@media(max-width:650px){.nav{align-items:flex-start;flex-direction:column}.hero{padding:52px 0}}
</style></head><body><header class="header"><div class="wrap nav"><div class="brand">STIT DARUL ILMI<small>Academic & Campus Information Portal</small></div><nav class="links"><a href="#tentang">Tentang</a><a href="#program">Program Studi</a><a href="#berita">Berita</a><a href="#kontak">Kontak</a></nav></div></header>
<section class="hero"><div class="wrap"><p style="font-weight:750;letter-spacing:.08em">STIT DARUL ILMI TASIKMALAYA</p><h1><?=h($campus['tagline']?:'Membangun Generasi Berilmu dan Berakhlak')?></h1><p><?=h($campus['about']?:'Selamat datang di portal informasi resmi STIT Darul Ilmi Tasikmalaya. Temukan informasi kampus, program studi, dan berita terkini.')?></p><?php if(!empty($campus['pmb_url'])):?><a class="btn" href="<?=h($campus['pmb_url'])?>">Informasi Penerimaan Mahasiswa Baru</a><?php endif;?></div></section>
<main class="wrap"><section class="section" id="tentang"><h2>Tentang Kampus</h2><div class="info"><p><?=nl2br(h($campus['about']?:'Profil kampus akan diperbarui oleh administrator.'))?></p><?php if(!empty($campus['vision'])):?><h3>Visi</h3><p><?=nl2br(h($campus['vision']))?></p><?php endif;?><?php if(!empty($campus['mission'])):?><h3>Misi</h3><p><?=nl2br(h($campus['mission']))?></p><?php endif;?></div></section>
<section class="section" id="program"><h2>Program Studi</h2><p class="muted">Program studi aktif yang tercatat pada sistem akademik.</p><div class="grid"><?php if(!$programs):?><div class="info">Informasi program studi akan segera tersedia.</div><?php endif;?><?php foreach($programs as $p):?><article class="info"><span class="tag"><?=h($p['code'])?> · <?=h($p['degree_level'])?></span><h3><?=h($p['name'])?></h3></article><?php endforeach;?></div></section>
<section class="section" id="berita"><h2>Berita & Informasi Kampus</h2><p class="muted">Pengumuman dan kegiatan resmi kampus.</p><div class="grid"><?php if(!$news):?><div class="info">Belum ada berita yang diterbitkan.</div><?php endif;?><?php foreach($news as $n):?><article class="card"><?php if($n['image_url']):?><img src="<?=h($n['image_url'])?>" alt="<?=h($n['title'])?>" loading="lazy"><?php endif;?><div class="cardbody"><span class="tag"><?=h($n['category'])?> · <?=h(date('d M Y',strtotime($n['published_at'])))?></span><h3><?=h($n['title'])?></h3><p class="muted"><?=h($n['excerpt']?:mb_substr(strip_tags($n['body']),0,180).'…')?></p><details><summary>Baca selengkapnya</summary><p><?=nl2br(h($n['body']))?></p></details></div></article><?php endforeach;?></div></section>
<section class="section" id="kontak"><h2>Kontak Kampus</h2><div class="info"><?php if(!empty($campus['address'])):?><p><strong>Alamat:</strong> <?=h($campus['address'])?></p><?php endif;?><?php if(!empty($campus['phone'])):?><p><strong>Telepon:</strong> <?=h($campus['phone'])?></p><?php endif;?><?php if(!empty($campus['email'])):?><p><strong>Email:</strong> <a href="mailto:<?=h($campus['email'])?>"><?=h($campus['email'])?></a></p><?php endif;?><?php if(!empty($campus['website'])):?><p><strong>Website:</strong> <a href="<?=h($campus['website'])?>"><?=h($campus['website'])?></a></p><?php endif;?></div></section></main>
<footer class="footer"><div class="wrap">© <?=date('Y')?> STIT Darul Ilmi Tasikmalaya · Academic Portal</div></footer></body></html>
